from pathlib import Path
import json,sys
expected=['S1_8K_OK','TEST=C005_P15','AP_READY=1','BAD_RECOVERY_AUTH=1','BAD_RECOVERY_EPOCH=02','BAD_OLD_WRITER_APPLY=W','BAD_AFTER_A=11','BAD_AFTER_B=44','GOOD_RECOVERY_AUTH=1','GOOD_RECOVERY_EPOCH=02','GOOD_OLD_WRITER_APPLY=R','GOOD_AFTER_A=11','GOOD_AFTER_B=22','AP_DONE=1','DONE']
trace=Path(sys.argv[1]).read_text(encoding='ascii',errors='replace').splitlines();checks={'trace_exact':trace==expected,'explicit_recovery_authority_present':all(x in trace for x in ['BAD_RECOVERY_AUTH=1','GOOD_RECOVERY_AUTH=1']),'bad_old_writer_corrupts_recovered_state':all(x in trace for x in ['BAD_RECOVERY_EPOCH=02','BAD_OLD_WRITER_APPLY=W','BAD_AFTER_A=11','BAD_AFTER_B=44']),'good_old_writer_currentness_rejects':all(x in trace for x in ['GOOD_RECOVERY_EPOCH=02','GOOD_OLD_WRITER_APPLY=R','GOOD_AFTER_A=11','GOOD_AFTER_B=22']),'two_cpu_participation':all(x in trace for x in ['AP_READY=1','AP_DONE=1'])};out={'format':'C005_P15_EVALUATION_V1','passed':all(checks.values()),'checks':checks,'trace':trace};Path(sys.argv[2]).write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
